#!/bin/sh
set -eu
tar -xf source.tar
stage="$PWD/stage"
cd source
mkdir -p "$stage/objects" "$stage/include/gio-core-2.0/gio" "$stage/pkgconfig"
objects=
compiled=0
for source in gio/gapplication.c gio/gapplicationcommandline.c gio/gapplicationimpl-dbus.c gio/gactiongroupexporter.c gio/gmenuexporter.c gio/gnotification.c gio/gnotificationbackend.c gio/ggtknotificationbackend.c gio/gportalnotificationbackend.c gio/gappinfo.c gio/gdesktopappinfo.c gio/gcontextspecificgroup.c gio/gdocumentportal.c gio/gopenuriportal.c gio/gportalsupport.c gio/gsandbox.c gio/gkeyfilesettingsbackend.c gio/xdp-dbus.c gio/gfdonotificationbackend.c gio/glocalfilemonitor-wasm-posix.c port/browser-file-monitor.c gio/gthreadedsocketservice.c gio/gdatagrambased.c gio/gsocket-wasm-posix.c gio/gsocketaddress.c gio/gsocketaddressenumerator.c gio/gsocketconnectable.c gio/gsocketconnection.c gio/gsocketcontrolmessage.c gio/gsocketinputstream.c gio/gsocketoutputstream.c gio/gsocketlistener.c gio/gsocketservice.c gio/gunixsocketaddress.c gio/gunixconnection.c gio/gcredentials-wasm-posix.c gio/gunixcredentialsmessage-wasm-posix.c gio/gunixfdmessage.c gio/gnetworking.c gio/ginetaddress.c gio/ginetsocketaddress.c gio/gnativesocketaddress.c gio/gproxyaddress.c gio/gproxyaddressenumerator.c gio/gtcpconnection.c gio/gtcpwrapperconnection.c gio/gnetworkaddress.c gio/gnetworkservice.c gio/gresolver.c gio/gthreadedresolver-wasm-posix.c gio/gproxyresolver.c gio/gdummyproxyresolver.c gio/gsocketclient.c gio/gproxy.c gio/gsocks4proxy.c gio/gsocks4aproxy.c gio/gsocks5proxy.c gio/ghttpproxy.c gio/gdbusobjectmanager.c gio/gdbusobjectmanagerserver.c gio/gdbusdaemon.c gio/gdbusauthobserver.c gio/gdbusauthmechanismanon.c gio/gdbusinterfaceskeleton.c gio/gdbuserror.c gio/gdbusobjectskeleton.c gio/gdbusactiongroup.c gio/gdbusauthmechanismexternal.c gio/gdbusnameowning.c gio/gdbusauthmechanism.c gio/gdbusobject.c gio/gdbusaddress.c gio/gdbusprivate.c gio/gdbusmessage.c gio/gdbusinterface.c gio/gdbusobjectproxy.c gio/gdbusserver.c gio/gdbusauthmechanismsha1.c gio/gdbusnamewatching.c gio/gdbusproxy.c gio/gdbusmethodinvocation.c gio/gdbusobjectmanagerclient.c gio/gdbusmenumodel.c gio/gdbusconnection.c gio/gtlsserverconnection.c gio/gtlsdatabase.c gio/gtlspassword.c gio/gtlsfiledatabase.c gio/gtlsclientconnection.c gio/gtlsbackend.c gio/gtlscertificate.c gio/gtlsinteraction.c gio/gtlsconnection.c gio/gdtlsclientconnection.c gio/gdtlsserverconnection.c gio/gdtlsconnection.c gio/gdbusauth-wasm-posix.c gio/gdummytlsbackend.c gio/gdbus-daemon-generated.c gio/gsrvtarget.c port/local-ipc-modules.c gio/gdbusintrospection.c gio/gdbusutils.c gio/gsubprocess.c gio/gsubprocesslauncher.c gio/gunixfdlist-wasm-posix.c gio/gfile-wasm-posix.c gio/gfileenumerator.c gio/gfileinputstream.c gio/gfileoutputstream.c gio/gfileiostream.c gio/gfileicon.c gio/gfilemonitor.c gio/gpollfilemonitor.c gio/gdummyfile.c gio/glocalfile-wasm-posix.c gio/glocalfileenumerator.c gio/glocalfileinfo.c gio/glocalfileinputstream.c gio/glocalfileoutputstream.c gio/glocalfileiostream.c gio/glocalvfs.c gio/gresourcefile.c gio/gvfs.c gio/gdrive.c gio/gmount.c gio/gmountoperation.c gio/gvolume.c gio/gvolumemonitor.c gio/gnativevolumemonitor.c gio/gunionvolumemonitor.c gio/gcontenttype.c gio/gcontenttype-fdo.c gio/thumbnail-verify.c gio/xdgmime/xdgmimeicon.c gio/xdgmime/xdgmime.c gio/xdgmime/xdgmimeglob.c gio/xdgmime/xdgmimeint.c gio/xdgmime/xdgmimemagic.c gio/xdgmime/xdgmimealias.c gio/xdgmime/xdgmimecache.c gio/xdgmime/xdgmimeparent.c gio/gpermission.c gio/gsimplepermission.c gio/gdelayedsettingsbackend.c gio/gmemorysettingsbackend.c gio/gnullsettingsbackend.c gio/gsettingsbackend.c gio/gsettingsschema.c gio/gsettings.c gio/gmarshal-internal.c gio/giomodule-wasm-posix.c gio/giomodule-priv.c gio/gsettings-mapping.c gio/gaction.c gio/gactiongroup.c gio/gactionmap.c gio/gsimpleaction.c gio/gsimpleactiongroup.c gio/gpropertyaction.c gio/gremoteactiongroup.c gio/gmenumodel.c gio/gmenu.c gio/gfiledescriptorbased.c gio/giounix-private-wasm-posix.c gio/gioscheduler.c gio/gasyncresult.c gio/gcancellable.c gio/gtask.c gio/ginputstream.c gio/goutputstream.c gio/giostream.c gio/gmemoryinputstream.c gio/gmemoryoutputstream.c gio/gseekable.c gio/gpollableinputstream.c gio/gpollableoutputstream.c gio/gpollableutils.c gio/gioerror.c gio/gsimpleasyncresult.c gio/gfilterinputstream.c gio/gfilteroutputstream.c gio/gbufferedinputstream.c gio/gbufferedoutputstream.c gio/gdatainputstream.c gio/gdataoutputstream.c gio/gconverter.c gio/gconverterinputstream.c gio/gconverteroutputstream.c gio/gzlibcompressor.c gio/gzlibdecompressor.c gio/gcharsetconverter.c gio/gunixinputstream.c gio/gunixoutputstream.c gio/ginitable.c gio/gasyncinitable.c gio/gresource-wasm-posix.c gio/gioenumtypes.c gvdb/gvdb-reader.c gio/gfileinfo.c gio/gfileattribute.c gio/gloadableicon.c gio/gthemedicon.c gio/gbytesicon.c gio/gemblem.c gio/gemblemedicon.c gio/gicon.c; do
 object="$stage/objects/${source##*/}.o"
 cc -DHAVE_CONFIG_H -DXDG_PREFIX=_gio_xdg -DGIO_COMPILATION '-DG_LOG_DOMAIN="GLib-GIO"' -I. -Igio -Igmodule -I/usr/local/include/glib-2.0/glib -I/usr/local/include/glib-2.0 -I/usr/local/include -c "$source" -o "$object"
 objects="$objects $object"
 compiled=$((compiled + 1))
 if [ $((compiled % 25)) -eq 0 ]; then echo "GIO: $compiled / 207 source files"; fi
done
ar rcs "$stage/libgio-core.a" $objects
cc -DGMODULE_COMPILATION -I. -Igmodule -I/usr/local/include/glib-2.0 -I/usr/local/include/glib-2.0/glib -c gmodule/gmodule.c -o "$stage/objects/gmodule.o"
cc -DG_MODULE_IMPL=1 -DG_MODULE_IMPL_DL=1 -DG_MODULE_IMPL_AR=7 -I. -I/usr/local/include/glib-2.0 -c gmodule/gmodule-deprecated.c -o "$stage/objects/gmodule-deprecated.o"
ar rcs "$stage/libgmodule-2.0.a" "$stage/objects/gmodule.o" "$stage/objects/gmodule-deprecated.o"
cc -shared "$stage/objects/gmodule.o" "$stage/objects/gmodule-deprecated.o" -lglib-2.0 -Wl,-soname,libgmodule-2.0.so -o "$stage/libgmodule-2.0.so"
cc -shared $objects -L"$stage" -lgmodule-2.0 -lgio-listmodel -lgobject-2.0 -lglib-2.0 -lz -lintl -Wl,-soname,libgio-core.so -o "$stage/libgio-core.so"
cp gio/gapplication.h gio/gapplicationcommandline.h gio/gdesktopappinfo.h gio/gnotification.h gio/gactiongroupexporter.h gio/gmenuexporter.h gio/gthreadedsocketservice.h gio/gdatagrambased.h gio/gcredentials.h gio/gdbusactiongroup.h gio/gdbusaddress.h gio/gdbusauthobserver.h gio/gdbusconnection.h gio/gdbuserror.h gio/gdbusinterface.h gio/gdbusinterfaceskeleton.h gio/gdbusmenumodel.h gio/gdbusmessage.h gio/gdbusmethodinvocation.h gio/gdbusnameowning.h gio/gdbusnamewatching.h gio/gdbusobject.h gio/gdbusobjectmanager.h gio/gdbusobjectmanagerclient.h gio/gdbusobjectmanagerserver.h gio/gdbusobjectproxy.h gio/gdbusobjectskeleton.h gio/gdbusproxy.h gio/gdbusserver.h gio/gdtlsclientconnection.h gio/gdtlsconnection.h gio/gdtlsserverconnection.h gio/ginetaddress.h gio/ginetsocketaddress.h gio/gnativesocketaddress.h gio/gnetworkaddress.h gio/gnetworkservice.h gio/gproxy.h gio/gproxyaddress.h gio/gproxyaddressenumerator.h gio/gproxyresolver.h gio/gresolver.h gio/gsocket.h gio/gsocketaddress.h gio/gsocketaddressenumerator.h gio/gsocketclient.h gio/gsocketconnectable.h gio/gsocketconnection.h gio/gsocketcontrolmessage.h gio/gsocketlistener.h gio/gsocketservice.h gio/gsrvtarget.h gio/gtcpconnection.h gio/gtcpwrapperconnection.h gio/gtlsbackend.h gio/gtlscertificate.h gio/gtlsclientconnection.h gio/gtlsconnection.h gio/gtlsdatabase.h gio/gtlsfiledatabase.h gio/gtlsinteraction.h gio/gtlspassword.h gio/gtlsserverconnection.h gio/gunixconnection.h gio/gunixcredentialsmessage.h gio/gunixsocketaddress.h gio/gnetworking.h gio/gdbusintrospection.h gio/gdbusutils.h gio/gsubprocess.h gio/gsubprocesslauncher.h gio/gunixfdlist.h gio/gfile.h gio/gfileenumerator.h gio/gfileinputstream.h gio/gfileoutputstream.h gio/gfileiostream.h gio/gfileicon.h gio/gfilemonitor.h gio/gvfs.h gio/gdrive.h gio/gmount.h gio/gmountoperation.h gio/gvolume.h gio/gvolumemonitor.h gio/gnativevolumemonitor.h gio/gcontenttype.h gio/gpermission.h gio/gsimplepermission.h gio/gsettings.h gio/gsettingsschema.h gio/gsettingsbackend.h gio/giomodule.h gio/gaction.h gio/gactiongroup.h gio/gactionmap.h gio/gsimpleaction.h gio/gsimpleactiongroup.h gio/gpropertyaction.h gio/gremoteactiongroup.h gio/gmenumodel.h gio/gmenu.h gio/gappinfo.h gio/gasyncinitable.h gio/gasyncresult.h gio/gbufferedinputstream.h gio/gbufferedoutputstream.h gio/gbytesicon.h gio/gcancellable.h gio/gcharsetconverter.h gio/gconverter.h gio/gconverterinputstream.h gio/gconverteroutputstream.h gio/gdatainputstream.h gio/gdataoutputstream.h gio/gemblem.h gio/gemblemedicon.h gio/gfileattribute.h gio/gfileinfo.h gio/gfilterinputstream.h gio/gfilteroutputstream.h gio/gicon.h gio/ginitable.h gio/ginputstream.h gio/gio-visibility.h gio/gio.h gio/gioenums.h gio/gioenumtypes.h gio/gioerror.h gio/giostream.h gio/giotypes.h gio/glistmodel.h gio/gloadableicon.h gio/gmemoryinputstream.h gio/gmemoryoutputstream.h gio/goutputstream.h gio/gpollableinputstream.h gio/gpollableoutputstream.h gio/gpollableutils.h gio/gresource.h gio/gseekable.h gio/gsimpleasyncresult.h gio/gtask.h gio/gthemedicon.h gio/gunixinputstream.h gio/gunixoutputstream.h gio/gzlibcompressor.h gio/gzlibdecompressor.h "$stage/include/gio-core-2.0/gio/"
cp port/*.pc "$stage/pkgconfig/"

mkdir -p "$stage/include/gio-core-2.0/gmodule"
cp gmodule/gmodule.h "$stage/include/gio-core-2.0/"
cp gmodule/gmodule-visibility.h "$stage/include/gio-core-2.0/gmodule/"

mkdir -p "$stage/bin"
cc -DHAVE_CONFIG_H -I. gio/gio-launch-desktop.c -o "$stage/bin/gio-launch-desktop"

cc -I. -Igio -Igmodule -I/usr/local/include/glib-2.0 -I/usr/local/include port/guc-session.c -L"$stage" -lgio-core -lgmodule-2.0 -lgobject-2.0 -lglib-2.0 -o "$stage/bin/guc-session"

mkdir -p "$DESTDIR/lib/pkgconfig" "$DESTDIR/include" "$DESTDIR/share/licenses/gio-core"
cp "$stage/"*.a "$stage/"*.so "$DESTDIR/lib/"
cp -R "$stage/include/." "$DESTDIR/include/"
cp "$stage/pkgconfig/"*.pc "$DESTDIR/lib/pkgconfig/"
cp ../COPYING "$DESTDIR/share/licenses/gio-core/COPYING"
mkdir -p "$DESTDIR/bin"
cp "$stage/bin/"* "$DESTDIR/bin/"
